   const nextMaterial=getMaterial(body),questionArea=body.split(/^#{1,4}\s*(?:材料|资料)/m)[0],answerMatch=questionArea.match(/\*\*答案\*\*\s*[：:]\s*([^\n]+)/),explainAt=questionArea.search(/\*\*(?:官方解析|解析)\*\*/),opts=[...questionArea.matchAll(/^-\s*\*\*([A-H])\*\*[.．、:]?\s*([\s\S]*?)(?=^-\s*\*\*[A-H]\*\*|\*\*答案\*\*)/gm)].map(m=>({key:m[1],text:m[2].replace(/\s*✅/g,'').trim()})),firstOpt=questionArea.search(/^-\s*\*\*[A-H]\*\*/m),stem=(firstOpt>=0?questionArea.slice(0,firstOpt):questionArea.split(/\*\*答案\*\*/)[0]).trim(),answer=answerLetters(answerMatch?.[1]);
   const q={id:'errrc-'+(qid||hash(path+':'+number)),qid:qid||'',number,category,subtype,paper,year:Number(meta['年份'])||0,region:meta['地区']||'',stem,options:opts,answer,explanation:explainAt<0?'来源未提供解析。':questionArea.slice(explainAt).replace(/^\*\*(?:官方解析|解析)\*\*\s*/,'').replace(/\n---\s*$/,'').trim(),material,materialId,path,source:'ERRRC/xingcezhenti',sourceType:'真题资料 · 上游原文',reviewRequired:!answer.length||opts.length<2};
